begin;
grant erp_api to postgres;
create or replace function public.erp_quote_get(p_org uuid,p_quote uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare q erp.quotes;begin if not erp_private.is_office(p_org) then raise exception 'Irodai jogosultság szükséges.' using errcode='42501';end if;select * into q from erp.quotes where organization_id=p_org and id=p_quote;if not found then raise exception 'Az ajánlat nem érhető el.' using errcode='42501';end if;return jsonb_build_object('quote',to_jsonb(q),'versions',(select jsonb_agg(to_jsonb(v)||jsonb_build_object('actor_name',(select p.display_name from erp.user_accounts a join erp.persons p on p.organization_id=a.organization_id and p.id=a.person_id where a.organization_id=p_org and a.auth_user_id=v.actor_id)) order by version) from erp.quote_versions v where organization_id=p_org and quote_id=p_quote),'events',coalesce((select jsonb_agg(to_jsonb(e)||jsonb_build_object('actor_name',(select p.display_name from erp.user_accounts a join erp.persons p on p.organization_id=a.organization_id and p.id=a.person_id where a.organization_id=p_org and a.auth_user_id=e.actor_id)) order by created_at) from erp.quote_events e where organization_id=p_org and quote_id=p_quote),'[]'),'project',(select jsonb_build_object('id',p.id,'status',p.work_status) from erp.garden_projects p where organization_id=p_org and accepted_quote_id=p_quote));end$$;
revoke erp_api from postgres;
commit;
